/**
 * emit to subscription queries of type FindDataBreach,
 * but only if the id matches
 *
 * @param		entity	DataBreach
 */
	protected void emitFindDataBreach( DataBreach entity ) {
		LOGGER.info("handling emitFindDataBreach" );
		
	    queryUpdateEmitter.emit(FindDataBreachQuery.class,
	                            query -> query.getFilter().getDataBreachId().equals(entity.getDataBreachId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDataBreach
	 * 
	 * @param		entity	DataBreach
	 */
	protected void emitFindAllDataBreach( DataBreach entity ) {
		LOGGER.info("handling emitFindAllDataBreach" );
		
	    queryUpdateEmitter.emit(FindAllDataBreachQuery.class,
	                            query -> true,
	                            entity);
	}

